CARDIO.register({"item":"d350","meta":{"num":"d350","label":"350","spe":"dermato","short":"Grosse jambe rouge aiguë","title":"Grosse jambe rouge aiguë","section":"D","chapter":23,"pages":"405-415","sdd":[{"num":54,"label":"Œdème localisé ou diffus"},{"num":85,"label":"Érythème"},{"num":87,"label":"Grosse jambe rouge aiguë"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"}]},"objectives":[{"id":"d350-obj-01","rank":"A","rubric":"Définition","title":"Définition de la grosse jambe rouge aiguë","desc":""},{"id":"d350-obj-02","rank":"A","rubric":"Définition","title":"Principales étiologies de la grosse jambe rouge aiguë","desc":""},{"id":"d350-obj-03","rank":"A","rubric":"Étiologies","title":"Connaître la principale cause de grosse jambe rouge aiguë fébrile","desc":"Érysipèle"},{"id":"d350-obj-04","rank":"B","rubric":"Étiologies","title":"Connaître les autres étiologies de grosse jambe rouge aiguë","desc":"Dermohypodermites infectieuses autres (pasteurellose après morsure), poussée d'insuffisance veineuse, eczéma aigu"},{"id":"d350-obj-05","rank":"A","rubric":"Examens complémentaires","title":"Connaître la pertinence des examens complémentaires (de l'érysipèle) dans un contexte de grosse jambe rouge (selon les caractéristiques cliniques et l'orientation diagnostique)","desc":""},{"id":"d350-obj-06","rank":"A","rubric":"Contenu multimédia","title":"Érysipèle de jambe typique","desc":""},{"id":"d350-obj-07","rank":"A","rubric":"Diagnostic positif","title":"Algorithme diagnostique","desc":""},{"id":"d350-obj-08","rank":"A","rubric":"Identifier une urgence","title":"Attitude/prise en charge clinique dans les situations d'urgence","desc":""},{"id":"d350-obj-09","rank":"A","rubric":"Identifier une urgence","title":"Savoir évoquer le diagnostic d'une fasciite nécrosante","desc":"Signes locaux, sepsis, comorbidités sous-jacentes, prise d'AINS"}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"d350-qroc-001","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["étiologie"],"difficulty":1,"question":"Quelle est, de loin, la cause la plus fréquente d'une grosse jambe rouge aiguë fébrile ?","answer":"L'érysipèle","accept":["érysipèle"],"keywords":["érysip"],"explanation":"C'est le premier diagnostic à évoquer : une dermohypodermite bactérienne aiguë d'origine streptococcique, dont le diagnostic est le plus souvent aisé.","src":"p. 406, 408"},{"id":"d350-qroc-002","type":"QROC","rank":"A","objective":"d350-obj-01","tags":["définition"],"difficulty":1,"question":"Dans la définition du tableau typique de grosse jambe rouge aiguë, quel seuil de température est cité ?","answer":"Fièvre d'au moins 38 °C","accept":["38","38 °C"],"keywords":["38"],"explanation":"Le tableau typique associe un placard érythémateux œdémateux assez bien limité, en général unilatéral, une fièvre d'au moins 38 °C et une installation en quelques heures, voire quelques jours.","src":"p. 406"},{"id":"d350-qroc-003","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["étiologie"],"difficulty":1,"question":"Quel germe est responsable de l'érysipèle (préciser le groupe du streptocoque) ?","answer":"Streptocoque β-hémolytique du groupe A","accept":["streptocoque A","streptocoque du groupe A","streptocoque bêta-hémolytique A","groupe A"],"keywords":["strepto"],"explanation":"C'est un streptocoque β-hémolytique du groupe A, plus rarement B, C ou G. Une porte d'entrée doit être recherchée systématiquement.","src":"p. 408"},{"id":"d350-qroc-004","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["épidémiologie"],"difficulty":1,"question":"Quelle proportion des érysipèles siège à la jambe ?","answer":"Plus de 80 %","accept":["80","plus de 80"],"keywords":["80"],"explanation":"La jambe est le siège de plus de 80 % des érysipèles ; l'atteinte des membres inférieurs est favorisée par l'insuffisance veineuse et/ou lymphatique, surtout chez l'adulte après 40 ans.","src":"p. 408"},{"id":"d350-qroc-005","type":"QROC","rank":"A","objective":"d350-obj-06","tags":["clinique"],"difficulty":2,"question":"Dans quelle localisation observe-t-on un bourrelet périphérique marqué autour du placard d'érysipèle ?","answer":"Le visage","accept":["visage","face"],"keywords":["visage"],"explanation":"Le bourrelet périphérique marqué n'est observé qu'au niveau du visage. À la jambe, le placard est érythémateux, œdémateux, circonscrit et douloureux à la palpation.","src":"p. 408"},{"id":"d350-qroc-006","type":"QROC","rank":"A","objective":"d350-obj-06","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quel élément faut-il rechercher systématiquement à l'examen d'un érysipèle (il est décelable cliniquement dans deux tiers des cas) ?","answer":"Une porte d'entrée","accept":["porte d'entrée"],"keywords":["porte"],"explanation":"Intertrigo inter-orteils, piqûre, érosion traumatique ou ulcère de jambe : la recherche de la porte d'entrée est indispensable.","src":"p. 408"},{"id":"d350-qroc-007","type":"QROC","rank":"A","objective":"d350-obj-05","tags":["paraclinique"],"difficulty":1,"question":"Devant un érysipèle typique sans comorbidité, quels examens complémentaires faut-il prescrire ?","answer":"Aucun","accept":["aucun","aucun examen","pas d'examen"],"keywords":["aucun"],"explanation":"Le diagnostic est clinique : devant un tableau typique et en l'absence de comorbidité, aucun examen complémentaire n'est nécessaire et le traitement ne doit pas être retardé.","src":"p. 408, 412"},{"id":"d350-qroc-008","type":"QROC","rank":"A","objective":"d350-obj-05","tags":["paraclinique"],"difficulty":2,"question":"Pourquoi les examens complémentaires ont-ils un intérêt limité, même dans les formes atypiques de dermohypodermite ?","answer":"Leur manque de sensibilité et de spécificité","accept":["manque de sensibilité","manque de spécificité","sensibilité et spécificité"],"keywords":["sensibilit","spécificit"],"explanation":"Les examens manquent de sensibilité et de spécificité : l'examen clinique reste primordial, y compris dans les formes atypiques.","src":"p. 412"},{"id":"d350-qroc-009","type":"QROC","rank":"A","objective":"d350-obj-05","tags":["biologie","pièges"],"difficulty":2,"question":"Pourquoi le dosage des D-dimères est-il inutile pour distinguer une thrombose veineuse d'une dermohypodermite infectieuse ?","answer":"Ils sont élevés dans la dermohypodermite infectieuse","accept":["élevés","augmentés"],"keywords":["élev"],"explanation":"Les D-dimères sont élevés en cas de dermohypodermite infectieuse : ils n'ont donc aucune valeur discriminative. En cas de suspicion de thrombose, on réalise une échographie-Doppler.","src":"p. 412"},{"id":"d350-qroc-010","type":"QROC","rank":"A","objective":"d350-obj-05","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Quel examen faut-il demander devant une grosse jambe rouge en cas de suspicion de thrombose veineuse ?","answer":"Échographie-Doppler des membres","accept":["écho-Doppler","échographie Doppler","Doppler"],"keywords":["doppler"],"explanation":"La thrombose veineuse se recherche par échographie-Doppler des membres ; les D-dimères ne permettent pas de trancher.","src":"p. 412"},{"id":"d350-qroc-011","type":"QROC","rank":"A","objective":"d350-obj-09","tags":["imagerie","urgence"],"difficulty":1,"question":"Quel examen d'imagerie apprécie l'extension en profondeur de la nécrose dans une dermohypodermite nécrosante ?","answer":"L'IRM","accept":["IRM","imagerie par résonance magnétique"],"keywords":["irm"],"explanation":"En cas de suspicion de dermohypodermite nécrosante, l'imagerie (échographie des parties molles, IRM) est à réaliser sans délai ; l'IRM précise l'extension en profondeur.","src":"p. 410, 412"},{"id":"d350-qroc-012","type":"QROC","rank":"A","objective":"d350-obj-02","tags":["traitement","étiologie"],"difficulty":2,"question":"Quel traitement est indispensable, mais parfois mal toléré, dans une dermohypodermite inflammatoire sur insuffisance veineuse ?","answer":"La contention élastique","accept":["contention","contention élastique"],"keywords":["contention"],"explanation":"La contention élastique est associée au repos et à des antalgiques.","src":"p. 415"},{"id":"d350-qroc-013","type":"QROC","rank":"A","objective":"d350-obj-09","tags":["urgence","diagnostic"],"difficulty":1,"question":"Quel diagnostic grave faut-il évoquer devant une grosse jambe rouge avec zones nécrotiques, hypoesthésie ou douleur spontanée intense, et crépitation ?","answer":"Une fasciite (dermohypodermite) nécrosante","accept":["fasciite nécrosante","dermohypodermite nécrosante","fasciite","gangrène gazeuse"],"keywords":["nécrosan"],"explanation":"Nécrose cutanée (pâleur, plaques noirâtres, livedo), hypoesthésie ou douleurs spontanées intenses, crépitation, extension malgré un traitement antibiotique bien conduit : ces signes imposent d'évoquer une fasciite nécrosante.","src":"p. 407, 410"},{"id":"d350-qroc-014","type":"QROC","rank":"A","objective":"d350-obj-09","tags":["urgence","pièges"],"difficulty":2,"question":"Quel élément évolutif sous antibiotiques doit faire évoquer une fasciite nécrosante devant un érysipèle présumé ?","answer":"Une extension malgré une antibiothérapie bien conduite","accept":["extension malgré","extension des lésions malgré"],"keywords":["extension","malgr"],"explanation":"L'extension des lésions malgré un traitement bien conduit est un signe de gravité. À l'inverse, une extension dans les 24 premières heures est fréquente et ne suffit pas à conclure.","src":"p. 407, 409"},{"id":"d350-qroc-015","type":"QROC","rank":"A","objective":"d350-obj-09","tags":["urgence","clinique"],"difficulty":2,"question":"Quel type de bulles est un marqueur de sévérité d'une dermohypodermite infectieuse ?","answer":"Des bulles hémorragiques","accept":["hémorragique"],"keywords":["hémorrag"],"explanation":"Les bulles hémorragiques figurent, avec la nécrose, la crépitation, l'hypoesthésie et le livedo, parmi les signes locaux de sévérité. Elles sont à distinguer des décollements bulleux superficiels que l'on observe parfois dans l'érysipèle.","src":"p. 407-408"},{"id":"d350-qroc-016","type":"QROC","rank":"A","objective":"d350-obj-09","tags":["urgence","traitement"],"difficulty":1,"question":"Quelle prise médicamenteuse faut-il rechercher et interrompre devant une dermohypodermite nécrosante ?","answer":"Les AINS","accept":["AINS","anti-inflammatoires non stéroïdiens","anti-inflammatoire"],"keywords":["ains"],"explanation":"La prise d'AINS est à rechercher et à interrompre dans la dermohypodermite nécrosante. Les AINS sont aussi à éviter comme antalgiques dans toute grosse jambe rouge.","src":"p. 410, 413-414"},{"id":"d350-qroc-017","type":"QROC","rank":"A","objective":"d350-obj-08","tags":["urgence","traitement"],"difficulty":1,"question":"Dans quel type de structure une dermohypodermite nécrosante doit-elle être prise en charge ?","answer":"Une unité de soins intensifs (prise en charge médico-chirurgicale)","accept":["soins intensifs","USI","réanimation"],"keywords":["intensif"],"explanation":"Fasciite nécrosante, gangrène gazeuse et dermohypodermite nécrosante sont des urgences vitales qui imposent une prise en charge médico-chirurgicale très rapide en soins intensifs.","src":"p. 410"},{"id":"d350-qroc-018","type":"QROC","rank":"A","objective":"d350-obj-08","tags":["urgence","traitement"],"difficulty":1,"question":"Quel geste chirurgical est indispensable dans le traitement d'une dermohypodermite nécrosante ?","answer":"Exciser toutes les zones nécrosées","accept":["excision","exciser","excision des zones nécrosées"],"keywords":["excis"],"explanation":"C'est une urgence médico-chirurgicale (+++) : excision de toutes les zones nécrosées en milieu spécialisé, avec antibiothérapie parentérale et correction de l'hypovolémie et des désordres glucidiques et électrolytiques.","src":"p. 415"},{"id":"d350-qroc-019","type":"QROC","rank":"A","objective":"d350-obj-08","tags":["traitement","urgence"],"difficulty":2,"question":"Quel antibiotique est associé à une pénicilline à spectre élargi (tazocilline) ou à une céphalosporine dans l'antibiothérapie parentérale d'une dermohypodermite nécrosante ?","answer":"La clindamycine","accept":["clindamycine"],"keywords":["clinda"],"explanation":"L'association parentérale comprend la clindamycine et une pénicilline à spectre élargi (tazocilline) ou une céphalosporine ; elle est adaptée ensuite à l'antibiogramme.","src":"p. 415"},{"id":"d350-qroc-020","type":"QROC","rank":"A","objective":"d350-obj-08","tags":["traitement","urgence"],"difficulty":2,"question":"Quel antibiotique ajoute-t-on en cas de suspicion de germes anaérobies dans une dermohypodermite nécrosante ?","answer":"Le métronidazole","accept":["métronidazole"],"keywords":["métronida"],"explanation":"Les germes d'une dermohypodermite nécrosante sont souvent associés (streptocoque, staphylocoque doré, bacilles à Gram négatif, anaérobies) ; le métronidazole est ajouté si des anaérobies sont suspectés.","src":"p. 410, 415"},{"id":"d350-qroc-021","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["traitement"],"difficulty":1,"question":"Quel est l'antibiotique de référence de l'érysipèle ?","answer":"L'amoxicilline","accept":["amoxicilline"],"keywords":["amoxi"],"explanation":"Le traitement doit être antistreptococcique : l'amoxicilline est l'antibiotique de référence.","src":"p. 414"},{"id":"d350-qroc-022","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["traitement"],"difficulty":1,"question":"Quelle classe d'antibiotiques constitue le traitement de première intention de l'érysipèle ?","answer":"Les β-lactamines","accept":["lactamines","bêta-lactamines"],"keywords":["lactamin"],"explanation":"Le traitement antistreptococcique repose en première intention sur les β-lactamines, avec l'amoxicilline comme molécule de référence.","src":"p. 414"},{"id":"d350-qroc-023","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["traitement"],"difficulty":1,"question":"Quelle est la durée totale de l'antibiothérapie d'un érysipèle sans signe de gravité ?","answer":"7 jours","accept":["7","7 jours","sept jours","une semaine"],"keywords":["7"],"explanation":"Le traitement oral à domicile dure 7 jours ; chez le malade hospitalisé, la durée totale de traitement est également de 7 jours.","src":"p. 414"},{"id":"d350-qroc-024","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["traitement"],"difficulty":2,"question":"Quelle dose quotidienne d'amoxicilline per os prescrire pour un érysipèle traité à domicile ?","answer":"3 à 4,5 g par jour","accept":["3 à 4,5 g","3 à 4,5","3-4,5 g"],"keywords":["3","4,5"],"explanation":"À domicile, en l'absence de signe de gravité : amoxicilline per os 3 à 4,5 g/jour pendant 7 jours, ce qui évite les contraintes et les effets indésirables du traitement IV.","src":"p. 414"},{"id":"d350-qroc-025","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["traitement"],"difficulty":2,"question":"Quelles sont les deux alternatives à la pénicilline en cas d'intolérance ou d'allergie dans l'érysipèle ?","answer":"Pristinamycine et clindamycine","accept":["pristinamycine ou clindamycine","clindamycine et pristinamycine"],"keywords":["pristina","clinda"],"explanation":"En cas d'intolérance ou d'allergie à la pénicilline, on prescrit la pristinamycine (3 g/jour en 3 prises) ou la clindamycine.","src":"p. 414"},{"id":"d350-qroc-026","type":"QROC","rank":"A","objective":"d350-obj-08","tags":["traitement"],"difficulty":1,"question":"Quelle mesure de repos est utile, quelle que soit la cause de la grosse jambe rouge, jusqu'à la régression des signes inflammatoires locaux ?","answer":"Repos au lit avec jambe surélevée","accept":["repos au lit jambe surélevée","repos jambe surélevée","repos avec surélévation de la jambe"],"keywords":["repos","surélev"],"explanation":"Le repos au lit avec la jambe surélevée diminue l'œdème et la douleur ; il est utile quelle que soit la cause.","src":"p. 413"},{"id":"d350-qroc-027","type":"QROC","rank":"A","objective":"d350-obj-08","tags":["traitement","pièges"],"difficulty":2,"question":"Dans quel cas un traitement anticoagulant à dose préventive est-il justifié devant une grosse jambe rouge ?","answer":"En cas de facteurs de risque de maladie thromboembolique","accept":["facteurs de risque de maladie thromboembolique","facteur de risque de maladie thromboembolique","facteurs de risque thromboembolique","risque thromboembolique"],"keywords":["risque","thrombo"],"explanation":"L'héparine calcique ou de bas poids moléculaire à dose préventive n'est justifiée qu'en présence de facteurs de risque de maladie thromboembolique, pas de façon systématique.","src":"p. 413"},{"id":"d350-qroc-028","type":"QROC","rank":"A","objective":"d350-obj-08","tags":["traitement","prévention"],"difficulty":1,"question":"Quelle vaccination faut-il vérifier et renouveler si besoin devant une grosse jambe rouge aiguë ?","answer":"La vaccination antitétanique","accept":["antitétanique","tétanos"],"keywords":["tétan"],"explanation":"La vérification de la vaccination antitétanique fait partie des mesures communes, quelle que soit la cause de la grosse jambe rouge.","src":"p. 413"},{"id":"d350-qroc-029","type":"QROC","rank":"A","objective":"d350-obj-08","tags":["traitement","urgence"],"difficulty":2,"question":"Après combien de temps de traitement sans amélioration une hospitalisation s'impose-t-elle ?","answer":"48 heures","accept":["48","48 h","2 jours"],"keywords":["48"],"explanation":"L'absence d'amélioration après 48 heures de traitement (ou une extension) est un critère d'hospitalisation, comme le doute diagnostique, les signes de gravité, les comorbidités ou un contexte social défavorable.","src":"p. 414"},{"id":"d350-qroc-030","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["suivi"],"difficulty":2,"question":"En combien de temps l'apyrexie, sous antibiotiques, signe-t-elle l'efficacité du traitement d'un érysipèle ?","answer":"48 à 72 heures","accept":["48 à 72","48-72 h","2 à 3 jours"],"keywords":["48","72"],"explanation":"L'apyrexie obtenue en 48 à 72 heures signe l'efficacité du traitement ; l'amélioration des signes locaux est plus lente, environ une semaine.","src":"p. 409"},{"id":"d350-qroc-031","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["suivi","pièges"],"difficulty":2,"question":"Pendant quelle période suivant le début du traitement une extension du placard d'érysipèle est-elle fréquente ?","answer":"Les 24 premières heures","accept":["24","24 h","24 heures"],"keywords":["24"],"explanation":"Une extension est fréquente dans les 24 premières heures de traitement ; c'est pourquoi les bordures sont marquées dès le début.","src":"p. 409"},{"id":"d350-qroc-032","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["suivi"],"difficulty":2,"question":"Quel geste simple, dès la première consultation, permet de suivre l'évolution locale d'un érysipèle ?","answer":"Marquer les bordures du placard","accept":["marquage","marquer"],"keywords":["marqu"],"explanation":"Un marquage initial des bordures permet de suivre l'évolution, notamment l'extension fréquente dans les 24 premières heures.","src":"p. 409"},{"id":"d350-qroc-033","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["complications"],"difficulty":1,"question":"Quelle est la complication la plus fréquente de l'érysipèle ?","answer":"La récidive","accept":["récidive"],"keywords":["récidiv"],"explanation":"La récidive survient dans environ 20 à 30 % des cas, en général en lien avec la persistance des facteurs de risque.","src":"p. 410"},{"id":"d350-qroc-034","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["complications"],"difficulty":2,"question":"Quelle complication locale de l'érysipèle, observée dans 5 à 10 % des cas (surtout si le traitement est retardé), doit être incisée et drainée ?","answer":"Un abcès localisé","accept":["abcès"],"keywords":["abcès"],"explanation":"Les abcès localisés doivent être incisés et drainés. Les complications systémiques (septicémie à streptocoques, glomérulonéphrite aiguë post-streptococcique) sont très rares (< 5 %).","src":"p. 410"},{"id":"d350-qroc-035","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["prévention"],"difficulty":2,"question":"Quelle prise en charge préventive est indiquée en cas de récidives multiples d'érysipèle ?","answer":"Une antibiothérapie préventive","accept":["antibiothérapie préventive","antibioprophylaxie","antibiotique préventif","prophylaxie antibiotique"],"keywords":["préven"],"explanation":"Les facteurs favorisants étant difficiles à contrôler, une antibiothérapie préventive est indiquée en cas de récidives multiples, en plus du traitement des portes d'entrée et de la prise en charge circulatoire.","src":"p. 414"},{"id":"d350-qroc-036","type":"QROC","rank":"A","objective":"d350-obj-03","tags":["prévention"],"difficulty":2,"question":"Quelle lésion cutanée du pied, porte d'entrée classique, faut-il diagnostiquer et traiter pour prévenir l'érysipèle de jambe ?","answer":"L'intertrigo inter-orteils","accept":["intertrigo"],"keywords":["intertrigo"],"explanation":"La prévention primaire repose sur le traitement des portes d'entrée (notamment l'intertrigo inter-orteils), l'amélioration des troubles circulatoires (contention, drainage lymphatique manuel, perte de poids) et l'hygiène cutanée.","src":"p. 414"},{"id":"d350-qroc-037","type":"QROC","rank":"A","objective":"d350-obj-07","tags":["diagnostic"],"difficulty":2,"question":"Quel diagnostic différentiel de l'érysipèle est plus circonscrit, moins inflammatoire et non fébrile, avec une piqûre de tique parfois non retrouvée ?","answer":"La borréliose (érythème annulaire centrifuge)","accept":["borréliose","érythème annulaire centrifuge"],"keywords":["borréli"],"explanation":"La borréliose, au stade d'érythème annulaire centrifuge ou plus tard, est plus circonscrite, moins inflammatoire et non fébrile ; la piqûre de tique n'est pas toujours établie.","src":"p. 413"},{"id":"d350-qroc-038","type":"QROC","rank":"A","objective":"d350-obj-07","tags":["diagnostic"],"difficulty":2,"question":"Quel diagnostic différentiel se manifeste par un trajet rouge inflammatoire (parfois placard linéaire) avec adénopathie inguinale homolatérale, et peut être associé à un érysipèle ?","answer":"La lymphangite","accept":["lymphangite"],"keywords":["lymphang"],"explanation":"La lymphangite associe un trajet rouge inflammatoire et souvent une adénopathie inguinale homolatérale ; elle n'exclut pas un érysipèle, auquel elle peut être associée.","src":"p. 413"},{"id":"d350-qroc-039","type":"QROC","rank":"A","objective":"d350-obj-02","tags":["traitement","étiologie"],"difficulty":2,"question":"Quelle orientation initiale donne-t-on à l'antibiothérapie probabiliste des dermohypodermites bactériennes autres que l'érysipèle ?","answer":"Antistreptococcique et antistaphylococcique","accept":["antistreptococcique et antistaphylococcique","streptocoque et staphylocoque"],"keywords":["streptoc","staphyl"],"explanation":"L'antibiothérapie est probabiliste, d'abord antistreptococcique et antistaphylococcique, puis adaptée si possible aux germes identifiés (prélèvements de porte d'entrée, hémocultures).","src":"p. 414"},{"id":"d350-qroc-040","type":"QROC","rank":"A","objective":"d350-obj-02","tags":["traitement"],"difficulty":2,"question":"Chez un diabétique atteint d'une dermohypodermite bactérienne, quelles sont les deux mesures (+++) préconisées avec l'antibiothérapie ?","answer":"Équilibre glycémique et immobilisation du pied","accept":["équilibre glycémique et immobilisation du pied","immobilisation du pied et équilibre glycémique"],"keywords":["glyc","immobilis"],"explanation":"On recherche l'équilibre glycémique (+++) et l'immobilisation du pied (+++), porte d'entrée habituelle sur un mal perforant ; un geste chirurgical sur une collection peut être nécessaire.","src":"p. 414-415"},{"id":"d350-qroc-041","type":"QROC","rank":"B","objective":"d350-obj-04","tags":["étiologie"],"difficulty":1,"question":"Quel germe est responsable d'une dermohypodermite aiguë survenant après une morsure de chat ou de chien ?","answer":"Pasteurella multocida","accept":["Pasteurella"],"keywords":["pasteurell"],"explanation":"La pasteurellose d'inoculation, due à Pasteurella multocida, fait partie des autres dermohypodermites bactériennes aiguës à connaître.","src":"p. 412"},{"id":"d350-qroc-042","type":"QROC","rank":"B","objective":"d350-obj-04","tags":["traitement"],"difficulty":2,"question":"Quelle antibiothérapie de référence en cas de dermohypodermite après morsure animale ?","answer":"Amoxicilline + acide clavulanique","accept":["amoxicilline et acide clavulanique","amoxicilline acide clavulanique","amoxicilline-acide clavulanique"],"keywords":["amoxi","clavul"],"explanation":"L'amoxicilline associée à l'acide clavulanique est l'antibiotique de référence ; en cas d'allergie aux β-lactamines, on utilise un macrolide ou la pristinamycine.","src":"p. 415"},{"id":"d350-qroc-043","type":"QROC","rank":"B","objective":"d350-obj-04","tags":["étiologie","clinique"],"difficulty":1,"question":"Quelle porte d'entrée est fréquente dans la dermohypodermite subaiguë du pied chez le diabétique ?","answer":"Un mal perforant plantaire","accept":["mal perforant"],"keywords":["perforant"],"explanation":"Cette dermohypodermite est torpide, avec une inflammation plus profonde et moins bien limitée qu'un érysipèle ; les germes sont principalement Staphylococcus aureus, Pseudomonas aeruginosa et des anaérobies.","src":"p. 411"},{"id":"d350-qroc-044","type":"QROC","rank":"B","objective":"d350-obj-04","tags":["complications"],"difficulty":2,"question":"Quelle complication osseuse faut-il rechercher de principe devant une dermohypodermite du pied diabétique ?","answer":"Une ostéite sous-jacente","accept":["ostéite"],"keywords":["ostéite"],"explanation":"On recherche de principe une ostéite sous-jacente et une décompensation du diabète ; l'évolution est moins favorable que celle d'un érysipèle, avec souvent un geste chirurgical.","src":"p. 411"},{"id":"d350-qroc-045","type":"QROC","rank":"A","objective":"d350-obj-02","tags":["traitement","étiologie"],"difficulty":2,"question":"Quel est le traitement d'un eczéma aigu responsable d'une grosse jambe rouge ?","answer":"Éviction de l'allergène et dermocorticoïdes","accept":["éviction de l'allergène et dermocorticoïdes","allergène et dermocorticoïdes"],"keywords":["allergène","dermocortico"],"explanation":"On évince l'allergène supposé et on prescrit un traitement symptomatique par dermocorticoïdes.","src":"p. 415"},{"id":"d350-qcm-101","type":"QRM","rank":"A","objective":"d350-obj-06","tags":["clinique"],"difficulty":1,"stem":"Une femme de 64 ans consulte pour une jambe droite rouge apparue en quelques heures, avec une fièvre à 39,5 °C et des frissons. Quels éléments sont habituels dans un érysipèle typique ?","options":[{"t":"Un placard érythémateux, œdémateux, bien limité, douloureux","ok":true,"why":"C'est la lésion cutanée typique : plaque circonscrite, œdémateuse, douloureuse, en général unilatérale."},{"t":"Une fièvre élevée avec frissons, parfois quelques heures avant le placard","ok":true,"why":"Le début est brutal, avec une fièvre à 39-40 °C et des frissons qui précèdent souvent l'apparition du placard."},{"t":"Des adénopathies inflammatoires homolatérales, voire une lymphangite","ok":true,"why":"Elles sont fréquemment associées au placard."},{"t":"Un bourrelet périphérique net tout autour du placard de la jambe","ok":false,"why":"Le bourrelet périphérique marqué n'est observé qu'au niveau du visage."},{"t":"Une atteinte bilatérale et symétrique d'emblée des deux jambes","ok":false,"why":"Le tableau typique est en général unilatéral."}],"explanation":"L'érysipèle typique associe un début brutal, une fièvre élevée avec frissons, une plaque érythémateuse œdémateuse circonscrite et douloureuse, et souvent une adénopathie homolatérale.","trap":"Le bourrelet périphérique est propre au visage : il ne s'observe pas à la jambe.","src":"p. 406, 408"},{"id":"d350-qcm-102","type":"QRM","rank":"A","objective":"d350-obj-03","tags":["étiologie","épidémiologie"],"difficulty":2,"stem":"À propos de l'érysipèle, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Il est dû à un streptocoque β-hémolytique du groupe A","ok":true,"why":"Les groupes B, C ou G sont plus rarement en cause, d'où un traitement antistreptococcique."},{"t":"Il siège le plus souvent au niveau du membre supérieur","ok":false,"why":"La jambe est le siège de plus de 80 % des érysipèles."},{"t":"Il touche surtout l'enfant de moins de 10 ans","ok":false,"why":"Il survient chez l'adulte après 40 ans, avec un âge moyen vers 60 ans."},{"t":"Le staphylocoque doré est le germe habituellement responsable","ok":false,"why":"L'agent habituel est un streptocoque β-hémolytique, pas le staphylocoque doré."},{"t":"Aucune porte d'entrée n'est jamais décelable cliniquement","ok":false,"why":"Une porte d'entrée est décelable cliniquement dans deux tiers des cas et sa recherche est indispensable."}],"explanation":"L'érysipèle est une dermohypodermite aiguë à streptocoque β-hémolytique du groupe A, localisée à la jambe dans plus de 80 % des cas, chez l'adulte après 40 ans.","src":"p. 408"},{"id":"d350-qcm-103","type":"QRM","rank":"A","objective":"d350-obj-05","tags":["paraclinique","pièges"],"difficulty":2,"stem":"Concernant les examens complémentaires devant une grosse jambe rouge aiguë, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Les D-dimères sont élevés en cas de dermohypodermite infectieuse, sans valeur discriminative","ok":true,"why":"Ils ne permettent donc pas de distinguer une thrombose veineuse d'une dermohypodermite infectieuse."},{"t":"Les hémocultures ont une forte rentabilité et sont indispensables dans l'érysipèle typique","ok":false,"why":"Leur rentabilité est faible et aucun examen n'est nécessaire dans un érysipèle typique."},{"t":"Un bacille à Gram négatif isolé d'un ulcère de jambe est forcément responsable de l'érysipèle","ok":false,"why":"Il peut simplement coloniser l'ulcère : l'interprétation est délicate."},{"t":"Une échographie-Doppler veineuse doit être réalisée chez tous les patients","ok":false,"why":"Elle est réservée aux cas où une thrombose veineuse est suspectée."},{"t":"Il faut attendre les résultats des examens avant de débuter l'antibiothérapie","ok":false,"why":"Le traitement ne doit pas être retardé par l'attente d'examens, qui ont en général peu d'intérêt diagnostique."}],"explanation":"Les examens complémentaires ont un intérêt limité et ne doivent jamais retarder le traitement : le diagnostic reste avant tout clinique.","src":"p. 412, 415"},{"id":"d350-qcm-104","type":"QRM","rank":"A","objective":"d350-obj-09","tags":["urgence"],"difficulty":2,"stem":"À propos des dermohypodermites nécrosantes (fasciite nécrosante, gangrène gazeuse), quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Ce sont des urgences vitales médico-chirurgicales","ok":true,"why":"La prise en charge se fait en unité de soins intensifs."},{"t":"Les signes locaux de gravité sont présents d'emblée","ok":true,"why":"Zones nécrotiques, anesthésie locale, écoulements fétides, crépitation."},{"t":"L'IRM est inutile car le diagnostic est uniquement clinique","ok":false,"why":"Une imagerie (échographie des parties molles, IRM) est à réaliser sans délai ; l'IRM apprécie l'extension en profondeur de la nécrose."},{"t":"Une antibiothérapie orale ambulatoire suffit si le patient n'a plus de fièvre","ok":false,"why":"Le traitement associe l'excision chirurgicale et une antibiothérapie parentérale en milieu spécialisé."},{"t":"Le germe en cause est toujours un streptocoque isolé","ok":false,"why":"Les germes (streptocoque, staphylocoque doré, bacilles à Gram négatif, anaérobies) sont souvent associés entre eux."}],"explanation":"Une dermohypodermite nécrosante est une urgence médico-chirurgicale : signes locaux de gravité d'emblée, imagerie sans délai, excision chirurgicale et antibiothérapie parentérale.","src":"p. 410, 412, 415"},{"id":"d350-qcm-105","type":"QRM","rank":"A","objective":"d350-obj-09","tags":["urgence","clinique"],"difficulty":2,"stem":"Parmi les éléments suivants, quel(s) est (sont) un (des) marqueur(s) de sévérité d'une dermohypodermite infectieuse ?","options":[{"t":"Des bulles hémorragiques","ok":true,"why":"Elles figurent parmi les signes locaux de sévérité, avec la nécrose, l'hypoesthésie, le livedo et la crépitation."},{"t":"Une adénopathie inguinale inflammatoire homolatérale isolée","ok":false,"why":"Elle est fréquente dans l'érysipèle typique et ne fait pas partie des marqueurs de sévérité."},{"t":"Un intertrigo inter-orteils retrouvé comme porte d'entrée","ok":false,"why":"C'est une porte d'entrée classique de l'érysipèle, pas un signe de gravité."},{"t":"Un placard unilatéral assez bien limité, douloureux à la palpation","ok":false,"why":"C'est l'aspect habituel de l'érysipèle typique."},{"t":"Une fièvre à 39 °C avec frissons au début, sans autre signe","ok":false,"why":"Une fièvre élevée avec frissons est habituelle dans l'érysipèle ; elle devient un signe de sévérité en cas de confusion ou de désorientation."}],"explanation":"Les marqueurs de sévérité associent des signes locaux (douleur intense, œdème majeur, bulles hémorragiques, nécrose, hypoesthésie, livedo, crépitation) et des signes généraux (confusion, tachypnée, tachycardie, oligurie, hypotension, pâleur).","src":"p. 407-408"},{"id":"d350-qcm-106","type":"QRM","rank":"A","objective":"d350-obj-08","tags":["traitement","urgence"],"difficulty":2,"stem":"Un homme de 66 ans présente une grosse jambe rouge avec des plaques noirâtres, une anesthésie locale, une crépitation et une hypotension. Quelle prise en charge est adaptée ?","options":[{"t":"Prise en charge médico-chirurgicale urgente avec excision des zones nécrosées","ok":true,"why":"C'est une urgence médico-chirurgicale (+++)."},{"t":"Antibiothérapie parentérale associant clindamycine et tazocilline (ou céphalosporine)","ok":true,"why":"Elle est adaptée ensuite à l'antibiogramme ; le métronidazole est ajouté si des anaérobies sont suspectés."},{"t":"Correction de l'hypovolémie et des désordres glucidiques et électrolytiques","ok":true,"why":"Elle fait partie du traitement de la dermohypodermite nécrosante."},{"t":"Traitement oral à domicile par amoxicilline à 3 g/jour pendant 7 jours, avec surveillance","ok":false,"why":"C'est le traitement d'un érysipèle sans signe de gravité."},{"t":"Antalgique de type AINS pour limiter l'inflammation locale et l'œdème de la jambe","ok":false,"why":"Les AINS sont à éviter ; leur prise est à rechercher et à interrompre."}],"explanation":"Le tableau est celui d'une dermohypodermite nécrosante : urgence médico-chirurgicale avec excision des zones nécrosées, antibiothérapie parentérale associée et correction des désordres hydroélectrolytiques.","src":"p. 410, 415"},{"id":"d350-qcm-107","type":"QRM","rank":"A","objective":"d350-obj-08","tags":["traitement","urgence"],"difficulty":2,"stem":"Quelle(s) situation(s) justifie(nt) une hospitalisation devant une grosse jambe rouge aiguë ?","options":[{"t":"Un doute diagnostique","ok":true,"why":"Il figure parmi les critères d'hospitalisation (traitement parentéral ou surveillance rapprochée)."},{"t":"L'absence d'amélioration après 48 heures de traitement","ok":true,"why":"Ce délai sans amélioration, ou une extension, impose l'hospitalisation."},{"t":"Une fièvre à 39 °C sur un érysipèle typique, sans comorbidité ni signe de gravité","ok":false,"why":"En l'absence de signes de gravité, un traitement oral à domicile est possible."},{"t":"Un âge supérieur à 40 ans","ok":false,"why":"C'est l'âge habituel de survenue de l'érysipèle, pas un critère d'hospitalisation."},{"t":"Un intertrigo inter-orteils retrouvé comme porte d'entrée","ok":false,"why":"C'est une porte d'entrée à traiter, pas un critère d'hospitalisation."}],"explanation":"L'hospitalisation ne s'impose que si un traitement parentéral ou une surveillance rapprochée sont nécessaires : doute diagnostique, signes de gravité, risque de complications locales, comorbidité, contexte social, absence d'amélioration à 48 heures ou extension.","src":"p. 414"},{"id":"d350-qcm-108","type":"QRM","rank":"A","objective":"d350-obj-08","tags":["traitement"],"difficulty":2,"stem":"Quelle(s) mesure(s) commune(s) s'applique(nt) à toute grosse jambe rouge aiguë, quelle que soit la cause ?","options":[{"t":"Repos au lit, jambe surélevée, jusqu'à régression des signes locaux","ok":true,"why":"Cela diminue l'œdème et la douleur."},{"t":"Vérification et mise à jour de la vaccination antitétanique","ok":true,"why":"Elle est à renouveler le cas échéant."},{"t":"Héparine à dose préventive systématique chez tous les patients","ok":false,"why":"Elle n'est justifiée qu'en cas de facteurs de risque de maladie thromboembolique."},{"t":"Marche active, jambe en position déclive, pour drainer l'œdème","ok":false,"why":"Le repos jambe surélevée est recommandé ; la douleur est aggravée par la position déclive."},{"t":"Antalgique de type AINS pour traiter la douleur","ok":false,"why":"Les antalgiques sont prescrits en évitant les AINS."}],"explanation":"Mesures communes : repos jambe surélevée, antalgiques sans AINS, vérification de la vaccination antitétanique, anticoagulation préventive seulement si facteurs de risque thromboembolique.","src":"p. 406, 413"},{"id":"d350-qcm-109","type":"QRM","rank":"A","objective":"d350-obj-03","tags":["complications"],"difficulty":2,"stem":"Parmi les propositions suivantes sur les complications de l'érysipèle, laquelle (lesquelles) est (sont) exacte(s) ?","options":[{"t":"La récidive est la complication la plus fréquente","ok":true,"why":"Elle survient dans environ 20 à 30 % des cas, en lien avec la persistance des facteurs de risque."},{"t":"Les complications locales surviennent dans plus de la moitié des cas","ok":false,"why":"Elles surviennent dans 5 à 10 % des cas, surtout en cas de retard au traitement."},{"t":"La septicémie à streptocoques est la complication la plus fréquente","ok":false,"why":"Elle est très rare (< 5 % des cas) ; la récidive est la complication la plus fréquente."},{"t":"Un abcès localisé se traite par antibiothérapie seule, sans drainage","ok":false,"why":"Les abcès localisés doivent être incisés et drainés."},{"t":"La glomérulonéphrite aiguë post-streptococcique est une complication habituelle","ok":false,"why":"Elle est possible mais très rare, comme les autres complications systémiques."}],"explanation":"Récidive fréquente (20 à 30 %), abcès locaux (5 à 10 %, surtout si traitement retardé), complications systémiques très rares (< 5 %).","src":"p. 410"},{"id":"d350-qcm-110","type":"QRM","rank":"A","objective":"d350-obj-07","tags":["diagnostic"],"difficulty":2,"stem":"À propos du diagnostic différentiel d'un érysipèle de jambe, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La lymphangite peut être associée à un érysipèle","ok":true,"why":"Elle associe un trajet rouge inflammatoire et souvent une adénopathie inguinale homolatérale, mais n'exclut pas l'érysipèle."},{"t":"La borréliose est plus inflammatoire et plus fébrile que l'érysipèle","ok":false,"why":"Elle est au contraire plus circonscrite, moins inflammatoire et non fébrile."},{"t":"Une piqûre de tique est toujours retrouvée en cas de borréliose","ok":false,"why":"La piqûre de tique n'est pas toujours établie."},{"t":"Un lymphœdème chronique unilatéral ne peut jamais être confondu avec un érysipèle","ok":false,"why":"Ses poussées inflammatoires, d'origine infectieuse parfois incertaine, rendent le diagnostic différentiel difficile."},{"t":"La lymphangite exclut le diagnostic d'érysipèle","ok":false,"why":"Elle peut au contraire lui être associée."}],"explanation":"Diagnostics différentiels de l'érysipèle : lymphœdème chronique inflammatoire, borréliose (érythème annulaire centrifuge), lymphangite (parfois associée à l'érysipèle).","src":"p. 413"},{"id":"d350-qcm-111","type":"QRM","rank":"A","objective":"d350-obj-09","tags":["urgence","pièges"],"difficulty":3,"stem":"Un homme de 58 ans, obèse et diabétique, est traité depuis 36 heures par amoxicilline pour un érysipèle de jambe. La rougeur s'étend, avec des bulles hémorragiques et une zone d'hypoesthésie ; la pression artérielle est basse. Quelles décisions sont adaptées ?","options":[{"t":"Évoquer une dermohypodermite nécrosante et organiser une prise en charge urgente","ok":true,"why":"Extension malgré le traitement, bulles hémorragiques, hypoesthésie et hypotension sont des signes de gravité."},{"t":"Réaliser sans délai une imagerie (échographie des parties molles, IRM)","ok":true,"why":"L'imagerie est à réaliser sans délai en cas de suspicion de dermohypodermite nécrosante."},{"t":"Demander un bilan de gravité : enzymes musculaires, ionogramme, gaz du sang, coagulation","ok":true,"why":"C'est le bilan proposé en cas de signes de gravité."},{"t":"Poursuivre l'amoxicilline per os à domicile et réévaluer simplement dans 7 jours","ok":false,"why":"L'extension avec signes de gravité impose une prise en charge urgente, pas une simple réévaluation différée."},{"t":"Ajouter un AINS pour contrôler la douleur et l'inflammation locale","ok":false,"why":"Les AINS sont à éviter et leur prise est à rechercher et à interrompre."}],"explanation":"Extension malgré un traitement bien conduit, bulles hémorragiques, hypoesthésie, hypotension et comorbidités (obésité, diabète) imposent d'évoquer une dermohypodermite nécrosante : imagerie et bilan sans délai, prise en charge médico-chirurgicale.","trap":"Une extension dans les 24 premières heures est fréquente ; ici elle persiste à 36 heures et s'associe à des signes de gravité.","src":"p. 407, 409, 410, 412"},{"id":"d350-qcm-112","type":"QRM","rank":"A","objective":"d350-obj-05","tags":["biologie","urgence"],"difficulty":2,"stem":"Chez un patient présentant une dermohypodermite avec signes de gravité, quels examens font partie du bilan proposé ?","options":[{"t":"Enzymes musculaires","ok":true,"why":"Elles font partie du bilan en cas de signes de gravité."},{"t":"Gaz du sang, à la recherche d'une acidose métabolique","ok":true,"why":"Le pH est étudié pour dépister une acidose métabolique."},{"t":"Coagulation, à la recherche d'une coagulation intravasculaire disséminée","ok":true,"why":"Une coagulation intravasculaire disséminée est recherchée."},{"t":"Créatininémie et ionogramme sanguin","ok":true,"why":"Ils font partie du bilan de gravité."},{"t":"Dosage des D-dimères pour distinguer dermohypodermite et thrombose","ok":false,"why":"Les D-dimères sont élevés en cas de dermohypodermite infectieuse : ils n'ont pas de valeur discriminative."}],"explanation":"En cas de signes de gravité : enzymes musculaires, ionogramme, créatininémie, gaz du sang (acidose métabolique) et coagulation (CIVD). Les D-dimères ne discriminent pas.","src":"p. 412"},{"id":"d350-qcm-113","type":"QRM","rank":"A","objective":"d350-obj-03","tags":["prévention"],"difficulty":2,"stem":"Concernant la prévention des récidives d'érysipèle de jambe, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Une antibiothérapie préventive est indiquée en cas de récidives multiples","ok":true,"why":"Les facteurs favorisants étant difficiles à contrôler, elle est indiquée en cas de récidives multiples."},{"t":"Une antibiothérapie préventive est systématique dès le premier épisode","ok":false,"why":"Elle est réservée aux récidives multiples."},{"t":"Il est inutile de traiter un intertrigo inter-orteils une fois l'érysipèle guéri","ok":false,"why":"Le diagnostic et le traitement d'une porte d'entrée comme l'intertrigo font partie de la prévention."},{"t":"Le port de bandes de contention est déconseillé","ok":false,"why":"La contention fait partie des mesures qui améliorent les troubles circulatoires."},{"t":"L'hygiène cutanée n'intervient pas dans la prévention","ok":false,"why":"Sécher entre les orteils, désinfecter les plaies et surveiller les pieds des diabétiques sont recommandés."}],"explanation":"Prévention primaire : portes d'entrée, circulation (contention, drainage lymphatique, perte de poids), hygiène cutanée ; en cas de récidives multiples : antibiothérapie préventive.","src":"p. 414"},{"id":"d350-qcm-114","type":"QRM","rank":"A","objective":"d350-obj-03","tags":["suivi","pièges"],"difficulty":2,"stem":"Un érysipèle de jambe est traité à domicile depuis 24 heures par amoxicilline. Le placard a légèrement dépassé le marquage initial. Quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Une extension dans les 24 premières heures de traitement est fréquente","ok":true,"why":"Elle n'est pas en soi un signe d'échec ; le marquage initial permet de suivre l'évolution."},{"t":"Cette extension initiale traduit un échec et impose de changer d'antibiotique","ok":false,"why":"L'extension initiale est fréquente ; c'est l'absence d'amélioration après 48 heures (ou une extension persistante) qui conduit à l'hospitalisation."},{"t":"L'apyrexie est attendue en 8 à 10 jours","ok":false,"why":"L'apyrexie est obtenue en 48 à 72 heures ; l'évolution favorable complète prend 8 à 10 jours."},{"t":"Le marquage initial des bordures était inutile","ok":false,"why":"Il permet justement de suivre l'évolution locale."},{"t":"Une hospitalisation immédiate est systématique en cas d'extension","ok":false,"why":"Une extension dans les 24 premières heures est fréquente et ne justifie pas à elle seule l'hospitalisation."}],"explanation":"Sous antibiotiques : extension fréquente les 24 premières heures, apyrexie en 48 à 72 heures, amélioration locale plus lente (environ 1 semaine), évolution favorable en 8 à 10 jours.","src":"p. 409, 414"},{"id":"d350-qcm-115","type":"QRM","rank":"B","objective":"d350-obj-04","tags":["clinique","étiologie"],"difficulty":2,"stem":"Chez un patient diabétique, une dermohypodermite du pied et du tiers inférieur de jambe est suspectée. Quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La porte d'entrée est souvent un mal perforant plantaire","ok":true,"why":"Les germes sont principalement Staphylococcus aureus, Pseudomonas aeruginosa et des anaérobies."},{"t":"La fièvre est constante et la douleur toujours très intense","ok":false,"why":"La douleur est modérée et la fièvre parfois absente."},{"t":"L'évolution est plus favorable que celle d'un érysipèle","ok":false,"why":"Elle est moins favorable, avec mauvaise réponse au traitement anti-infectieux et geste chirurgical fréquent."},{"t":"Les lésions sont aussi nettement limitées que dans un érysipèle","ok":false,"why":"L'inflammation est plus profonde et moins bien limitée."},{"t":"La recherche d'une ostéite sous-jacente est inutile","ok":false,"why":"Une ostéite sous-jacente et une décompensation du diabète sont à rechercher de principe."}],"explanation":"Dermohypodermite du pied diabétique : évolution subaiguë, torpide, inflammation profonde et mal limitée, porte d'entrée fréquente sur un mal perforant, ostéite à rechercher.","src":"p. 411"},{"id":"d350-qcm-116","type":"QRM","rank":"B","objective":"d350-obj-04","tags":["étiologie","traitement"],"difficulty":2,"stem":"À propos des autres dermohypodermites bactériennes aiguës, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Une morsure de chat ou de chien expose à une pasteurellose (Pasteurella multocida)","ok":true,"why":"C'est la dermohypodermite à évoquer après morsure animale."},{"t":"Après morsure animale, l'antibiotique de référence est l'amoxicilline + acide clavulanique","ok":true,"why":"C'est le traitement de référence (3 g/jour d'amoxicilline per os ou IV)."},{"t":"En cas d'allergie aux β-lactamines après morsure : macrolide ou pristinamycine","ok":true,"why":"Ce sont les alternatives en cas d'allergie aux β-lactamines."},{"t":"Le rouget du porc (érysipéloïde) est dû à Pasteurella multocida, comme la pasteurellose","ok":false,"why":"Il est dû à Erysipelothrix rhusiopathiae."},{"t":"Le rouget du porc se voit surtout au pied, après une morsure de chat ou de chien","ok":false,"why":"Il survient surtout à la main, après une blessure par un os d'origine animale (bouchers)."}],"explanation":"Pasteurellose après morsure animale : amoxicilline + acide clavulanique ; rouget du porc : Erysipelothrix rhusiopathiae, main, bouchers.","src":"p. 412, 415"},{"id":"d350-qcm-117","type":"QRM","rank":"A","objective":"d350-obj-02","tags":["traitement","étiologie"],"difficulty":2,"stem":"Pour les dermohypodermites bactériennes autres que l'érysipèle, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"L'antibiothérapie est d'abord probabiliste, antistreptococcique et antistaphylococcique","ok":true,"why":"Elle est mal codifiée, d'où cette orientation initiale."},{"t":"Elle est ensuite adaptée aux germes identifiés (porte d'entrée, hémocultures)","ok":true,"why":"L'adaptation se fait selon les données bactériologiques."},{"t":"Chez le diabétique : équilibre glycémique et immobilisation du pied","ok":true,"why":"Ce sont deux mesures (+++) ; un geste chirurgical sur une collection peut aussi être nécessaire."},{"t":"Un geste chirurgical sur une collection n'est jamais nécessaire","ok":false,"why":"Un geste chirurgical sur une collection peut être nécessaire."},{"t":"L'antibiothérapie est d'emblée ciblée sur un germe identifié avant tout traitement","ok":false,"why":"Elle est probabiliste au départ."}],"explanation":"Autres dermohypodermites bactériennes : antibiothérapie probabiliste antistreptococcique et antistaphylococcique puis adaptée ; chez le diabétique, équilibre glycémique et immobilisation du pied.","src":"p. 414-415"},{"id":"d350-qru-101","type":"QRU","rank":"A","objective":"d350-obj-03","tags":["diagnostic"],"difficulty":1,"stem":"Un homme de 61 ans présente, depuis la veille, une fièvre à 39,5 °C avec frissons, puis une plaque rouge vif, œdémateuse, douloureuse et bien limitée de la jambe gauche, avec une adénopathie inguinale homolatérale et un intertrigo inter-orteils. Quel est le diagnostic le plus probable ?","options":[{"t":"Érysipèle","ok":true,"why":"Tableau typique : début brutal fébrile, placard circonscrit douloureux, adénopathie homolatérale, porte d'entrée interdigitale."},{"t":"Thrombose veineuse profonde isolée","ok":false,"why":"Elle ne donne pas de tableau de grosse jambe rouge ; elle peut rarement s'associer à un érysipèle."},{"t":"Borréliose au stade d'érythème annulaire centrifuge","ok":false,"why":"Elle est plus circonscrite, moins inflammatoire et non fébrile."},{"t":"Eczéma aigu de contact","ok":false,"why":"L'eczéma est prurigineux, avec des vésicules sur un placard à bords émiettés."},{"t":"Lymphangite isolée","ok":false,"why":"Elle se présente comme un trajet rouge linéaire et peut être associée à un érysipèle."}],"explanation":"Une grosse jambe rouge aiguë fébrile unilatérale avec porte d'entrée évoque en premier lieu un érysipèle.","src":"p. 406, 408"},{"id":"d350-qru-102","type":"QRU","rank":"A","objective":"d350-obj-05","tags":["paraclinique"],"difficulty":1,"stem":"Un homme de 55 ans, sans comorbidité, présente un érysipèle typique de jambe, sans signe de gravité. Quels examens complémentaires prescrivez-vous ?","options":[{"t":"Aucun examen complémentaire","ok":true,"why":"Devant un tableau typique et sans comorbidité, aucun examen n'est nécessaire."},{"t":"NFS, CRP et hémocultures systématiques","ok":false,"why":"Ils ne sont pas nécessaires dans l'érysipèle typique ; les hémocultures ont une faible rentabilité."},{"t":"Échographie-Doppler veineuse systématique des deux membres","ok":false,"why":"Elle est réservée aux cas où une thrombose veineuse est suspectée."},{"t":"IRM des parties molles en urgence","ok":false,"why":"L'imagerie sans délai est réservée à la suspicion de dermohypodermite nécrosante."},{"t":"Prélèvement bactériologique systématique de la porte d'entrée","ok":false,"why":"Il est utile surtout dans les formes graves."}],"explanation":"Le diagnostic est clinique : aucun examen complémentaire n'est nécessaire dans un érysipèle typique sans comorbidité.","src":"p. 408, 412"},{"id":"d350-qru-103","type":"QRU","rank":"A","objective":"d350-obj-03","tags":["traitement"],"difficulty":2,"stem":"Un homme de 52 ans, sans comorbidité, présente un érysipèle de jambe sans signe de gravité local ni général. Quelle prise en charge proposez-vous ?","options":[{"t":"Traitement oral à domicile par amoxicilline, 3 à 4,5 g/jour pendant 7 jours","ok":true,"why":"Sans signe de gravité, le traitement oral à domicile évite les contraintes et les effets indésirables du traitement IV."},{"t":"Hospitalisation systématique pour amoxicilline intraveineuse, puis relais oral","ok":false,"why":"L'hospitalisation est réservée aux cas de doute, de gravité, de comorbidité ou d'échec, pas systématique."},{"t":"Traitement oral à domicile par pristinamycine, 3 g/jour pendant 7 jours","ok":false,"why":"La pristinamycine est une alternative en cas d'intolérance ou d'allergie à la pénicilline."},{"t":"Association parentérale tazocilline et clindamycine en milieu spécialisé","ok":false,"why":"C'est le schéma de la dermohypodermite nécrosante."},{"t":"Amoxicilline per os 3 à 4,5 g/jour avec un AINS pendant 7 jours","ok":false,"why":"Les AINS sont à éviter."}],"explanation":"Érysipèle sans signe de gravité : traitement oral à domicile par amoxicilline 3 à 4,5 g/jour pendant 7 jours, sans AINS.","src":"p. 414"},{"id":"d350-qru-104","type":"QRU","rank":"A","objective":"d350-obj-03","tags":["traitement"],"difficulty":2,"stem":"Une femme de 70 ans, allergique à la pénicilline, présente un érysipèle de jambe sans signe de gravité. Quel antibiotique constitue une alternative ?","options":[{"t":"Pristinamycine","ok":true,"why":"En cas d'intolérance ou d'allergie à la pénicilline : pristinamycine (3 g/jour en 3 prises) ou clindamycine."},{"t":"Amoxicilline","ok":false,"why":"C'est l'antibiotique de référence de première intention ; les alternatives sont réservées à l'allergie ou à l'intolérance."},{"t":"Métronidazole","ok":false,"why":"Il est ajouté en cas de suspicion d'anaérobies dans une dermohypodermite nécrosante."},{"t":"Tazocilline","ok":false,"why":"Elle entre dans l'association parentérale de la dermohypodermite nécrosante, pas dans l'érysipèle sans gravité."},{"t":"Amoxicilline associée à l'acide clavulanique","ok":false,"why":"C'est l'antibiotique de référence après une morsure animale."}],"explanation":"Alternative en cas d'allergie ou d'intolérance à la pénicilline dans l'érysipèle : pristinamycine ou clindamycine.","src":"p. 414"},{"id":"d350-qru-105","type":"QRU","rank":"A","objective":"d350-obj-09","tags":["diagnostic","urgence"],"difficulty":2,"stem":"Parmi les éléments suivants, lequel doit faire évoquer une fasciite nécrosante plutôt qu'un érysipèle typique ?","options":[{"t":"Des plaques noirâtres avec zones livedoïdes et hypoesthésie","ok":true,"why":"Nécrose cutanée et hypoesthésie font partie des signes locaux de gravité."},{"t":"Une adénopathie inguinale inflammatoire homolatérale avec fièvre à 39 °C","ok":false,"why":"Elle est fréquente dans l'érysipèle typique."},{"t":"Un placard rouge vif, tendu et douloureux, avec quelques décollements bulleux superficiels","ok":false,"why":"Ces aspects sont possibles dans l'érysipèle (décollements liés à l'œdème dermique)."},{"t":"Un intertrigo inter-orteils retrouvé comme porte d'entrée","ok":false,"why":"C'est une porte d'entrée classique de l'érysipèle."},{"t":"Des frissons précédant de quelques heures l'apparition du placard","ok":false,"why":"Ce début brutal est habituel dans l'érysipèle."}],"explanation":"Nécrose cutanée (pâleur, plaques noirâtres, zones livedoïdes), hypoesthésie ou douleurs spontanées intenses, crépitation et extension malgré le traitement font évoquer une fasciite nécrosante.","src":"p. 407-408"},{"id":"d350-qru-106","type":"QRU","rank":"A","objective":"d350-obj-08","tags":["urgence","traitement"],"difficulty":2,"stem":"Lequel de ces patients atteints d'érysipèle justifie plutôt une hospitalisation ?","options":[{"t":"Un patient atteint d'une insuffisance rénale sévère","ok":true,"why":"La comorbidité (insuffisance rénale sévère, hépatique ou cardiaque, immunodépression, obésité morbide) justifie l'hospitalisation."},{"t":"Un patient de 45 ans sans comorbidité, fébrile à 39 °C, avec un intertrigo inter-orteils","ok":false,"why":"Un traitement oral à domicile est possible en l'absence de signes de gravité."},{"t":"Un patient de 60 ans avec adénopathie inguinale homolatérale, sans signe de gravité","ok":false,"why":"L'adénopathie est fréquente dans l'érysipèle et ne justifie pas à elle seule l'hospitalisation."},{"t":"Un patient dont la fièvre a disparu 48 heures après le début de l'amoxicilline","ok":false,"why":"L'apyrexie en 48 à 72 heures signe l'efficacité du traitement."},{"t":"Un patient dont le placard a un peu débordé le marquage dans les premières 12 heures","ok":false,"why":"Une extension est fréquente dans les premières 24 heures de traitement."}],"explanation":"Une comorbidité sévère fait partie des critères d'hospitalisation, comme le doute diagnostique, les signes de gravité, le contexte social ou l'absence d'amélioration à 48 heures.","src":"p. 409, 414"},{"id":"d350-qru-107","type":"QRU","rank":"B","objective":"d350-obj-04","tags":["clinique","étiologie"],"difficulty":2,"stem":"Une femme de 70 ans consulte pour une jambe rouge douloureuse, bilatérale, peu fébrile, évoluant depuis une semaine, sur un terrain de varices, de dermite ocre et de lipodermatosclérose. Quel diagnostic est le plus probable ?","options":[{"t":"Poussée inflammatoire d'insuffisance veineuse","ok":true,"why":"Poussées douloureuses subaiguës ou chroniques, le plus souvent bilatérales, peu ou pas fébriles, sur ce terrain."},{"t":"Érysipèle de jambe d'évolution subaiguë","ok":false,"why":"Il débute brutalement avec une fièvre élevée, en général unilatéral."},{"t":"Dermohypodermite nécrosante de début progressif","ok":false,"why":"Elle associe d'emblée des signes locaux de gravité et des signes généraux marqués."},{"t":"Lymphangite de la jambe avec adénopathie","ok":false,"why":"Elle se présente comme un trajet rouge linéaire avec adénopathie inguinale."},{"t":"Eczéma aigu de contact étendu à la jambe","ok":false,"why":"L'eczéma est prurigineux, avec des vésicules sur un placard à bords émiettés."}],"explanation":"Sur insuffisance veineuse chronique, les poussées inflammatoires sont douloureuses, subaiguës ou chroniques, le plus souvent bilatérales et peu ou pas fébriles ; le traitement repose sur la contention élastique, associée au repos et aux antalgiques.","src":"p. 410-411, 415"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d350-pareto","points":[{"id":"d350-par-01","rank":"A","cat":"définition","text":"GJRA typique = placard érythémateux œdémateux **unilatéral** + fièvre **≥ 38 °C**, début en heures → cause n° 1 = **érysipèle**","src":"p. 406"},{"id":"d350-par-02","rank":"A","cat":"étiologie","text":"Érysipèle = dermohypodermite à **streptocoque β-hémolytique A**, jambe > **80 %**, adulte > 40 ans, favorisé par insuffisance veineuse/lymphatique","src":"p. 408"},{"id":"d350-par-03","rank":"A","cat":"clinique","text":"Érysipèle : début brutal, fièvre **39-40 °C + frissons**, plaque rouge œdémateuse douloureuse, adénopathie ± lymphangite ; **porte d'entrée** à chercher ; bourrelet = **visage**","src":"p. 408"},{"id":"d350-par-04","rank":"A","cat":"examen","text":"Érysipèle typique sans comorbidité → **aucun examen complémentaire** ; ne jamais **retarder** le traitement pour des examens","src":"p. 408, 412, 415"},{"id":"d350-par-05","rank":"A","cat":"traitement","text":"Érysipèle : **amoxicilline** 3-4,5 g/j per os, **7 jours**, à domicile si pas de gravité ; allergie pénicilline → **pristinamycine** ou clindamycine","src":"p. 414"},{"id":"d350-par-06","rank":"A","cat":"gravité","text":"Évoquer **fasciite nécrosante** : douleur intense ou **hypoesthésie**, nécrose (noirâtre, livedo), **crépitation**, bulles hémorragiques, extension malgré ATB, signes de sepsis","src":"p. 407, 410"},{"id":"d350-par-07","rank":"A","cat":"traitement","text":"DHN = **urgence médico-chirurgicale** en soins intensifs : **excision** des zones nécrosées + ATB parentérale (**clindamycine** + tazocilline ou céphalosporine ; métronidazole si anaérobies)","src":"p. 410, 415"},{"id":"d350-par-08","rank":"A","cat":"piège","text":"**AINS** : à éviter (antalgiques sans AINS) et à rechercher puis **arrêter** devant une DHN","src":"p. 410, 413-414"},{"id":"d350-par-09","rank":"A","cat":"examen","text":"Suspicion de DHN : **imagerie sans délai** (écho parties molles, **IRM**) + bilan de gravité (CPK, iono, créat, GDS, coagulation) ; D-dimères **non discriminants** (élevés)","src":"p. 410, 412"},{"id":"d350-par-10","rank":"A","cat":"suivi","text":"Sous traitement : apyrexie en **48-72 h** = efficacité ; extension fréquente les **24 premières heures** → marquer les bordures ; sans amélioration à **48 h** → hospitaliser","src":"p. 409, 414"},{"id":"d350-par-11","rank":"A","cat":"gravité","text":"Hospitaliser si : doute diagnostique, **signes de gravité**, comorbidité (diabète déséquilibré, immunodépression, insuffisance sévère, obésité morbide), contexte social, **échec à 48 h**","src":"p. 414"},{"id":"d350-par-12","rank":"A","cat":"traitement","text":"Mesures communes : **repos jambe surélevée**, vaccination **antitétanique**, héparine préventive **seulement si facteurs de risque** thromboembolique ; écho-Doppler si doute sur une TVP","src":"p. 412-413"},{"id":"d350-par-13","rank":"A","cat":"gravité","text":"Complication la plus fréquente = **récidive** (20-30 %) ; locale : **abcès** (incision-drainage) ; très rares : septicémie, **GNA post-streptococcique**","src":"p. 410"},{"id":"d350-par-14","rank":"A","cat":"prévention","text":"Prévention : traiter la **porte d'entrée** (intertrigo inter-orteils), contention, perte de poids, hygiène cutanée ; **antibiothérapie préventive** si récidives multiples","src":"p. 414"},{"id":"d350-par-15","rank":"A","cat":"étiologie","text":"Diagnostics différentiels : **lymphœdème** chronique, **borréliose** (circonscrite, non fébrile), **lymphangite** (trajet rouge + adénopathie inguinale, peut s'associer à l'érysipèle)","src":"p. 413"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
